      {tab === "pulse" && <><section className="surface mb-4 p-3"><h2 className="mb-2 text-sm font-semibold">{text(preferences.language, "Правила совпадений", "Confluence rules")}</h2><div className="grid grid-cols-2 gap-2 sm:grid-cols-4"><NumberFilter label={text(preferences.language, "Минимум источников (2+)", "Minimum sources (2+)")} value={confluenceRules.minWallets} onChange={(value) => setConfluenceRules({ ...confluenceRules, minWallets: Math.max(2, Math.min(1000, Math.floor(value))) })}/><NumberFilter label={text(preferences.language, "Минимальный Quality (0–100)", "Minimum Quality (0–100)")} value={confluenceRules.minQuality} onChange={(value) => setConfluenceRules({ ...confluenceRules, minQuality: Math.min(100, value) })}/><NumberFilter label={text(preferences.language, "Минимальный Copyability (0–100)", "Minimum Copyability (0–100)")} value={confluenceRules.minCopyability} onChange={(value) => setConfluenceRules({ ...confluenceRules, minCopyability: Math.min(100, value) })}/><Toggle label={text(preferences.language, "Только подтверждённые активные", "Confirmed active positions only")} checked={confluenceRules.onlyOpen} onChange={(onlyOpen) => setConfluenceRules({ ...confluenceRules, onlyOpen })}/></div><p className="mt-2 text-xs text-[var(--muted)]">{text(preferences.language, "Коррелирующие адреса считаются одним источником. Это эвристика, не доказательство независимости владельцев. Неизвестный score не проходит заданный порог.", "Correlated addresses count as one source. This heuristic does not prove independent ownership. Unknown scores fail a nonzero threshold.")}</p>{confluenceError && <p role="status" className="mt-2 text-xs text-[var(--warn)]">{confluenceError}</p>}</section><PulseView preferences={preferences} fills={filteredFills} filters={activityFilters} setFilters={setActivityFilters} coins={coins} stats={fillStats} live={live} limit={activityLimit} setLimit={setActivityLimit} favorites={favorites} money={formatMoney} time={formatTime} onFavorite={toggleFavorite} onRemember={rememberWallet} onCopy={copy} confluences={confluences} confluenceMinutes={confluenceMinutes} exactWallets={initialData.tracked.length} onConfluenceMinutes={(value) => { void updatePreference("confluenceMinutes", value); }} coinFlow={initialData.coinFlow}/></>}
